class DateValue(TypedDict):
    """A date as a renderer takes it: its calendar's key and the numbers."""

    calendar: str
    year: int
    month: int
    day: int


class TimeValue(TypedDict):
    """A time of day as a renderer takes it."""

    hour: int
    minute: int
    second: int


class DateTimeValue(TypedDict):
    """A date and a time together."""

    date: DateValue
    time: TimeValue


class GhatiValue(TypedDict):
    """A ghati-pala count as a renderer takes it."""

    ghati: int
    pala: int
    vipala: int


class Renderer(Protocol):
    """What the accessors reach the locale engine through."""

    def render(self, key: str, params: Mapping[str, object] = {}) -> str:
        """The message with a key, rendered with its parameters."""
        ...

    def entity(self, key: str) -> "EntityForms":
        """A catalogued entity's forms in the current locale."""
        ...


@dataclass(frozen=True)
class EntityForms:
    """A catalogued entity's forms in the current locale."""

    iast: str

    name: str

    prose: str

    short: Optional[str] = None

    glyph: Optional[str] = None

    gender: Optional[Gender] = None

    forms: Mapping[str, str] = field(default_factory=dict)
    """Every form the locale carries, including any a loaded pack
    brought: a record's forms are an open set, and the named fields
    above are only the ones `i18n/` guarantees.
    """

    @classmethod
    def of(cls, raw: object) -> EntityForms:
        """The forms as the boundary hands them out, whether as the JSON
        text or as the object it parses to.
        """
        forms = json.loads(raw) if isinstance(raw, str) else raw
        assert isinstance(forms, dict)

        def text(form: str) -> Optional[str]:
            found = forms.get(form)
            return found if isinstance(found, str) else None

        return cls(
            iast=text("iast") or "",
            name=text("name") or "",
            prose=text("prose") or "",
            short=text("short"),
            forms={
                name: value
                for name, value in forms.items()
                if isinstance(value, str)
            },
            glyph=text("glyph"),
            gender=next(
                (g for g in Gender if g.value == text("gender")), None
            ),
        )


